import{_ as e,o,c as t,a2 as d}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Tabela Geral de Divisão de Eras","description":"","frontmatter":{},"headers":[],"relativePath":"pt/70-纪元划分总表.md","filePath":"pt/70-纪元划分总表.md","lastUpdated":1789183869000}'),r={name:"pt/70-纪元划分总表.md"};function i(s,a,n,c,l,m){return o(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="tabela-geral-de-divisao-de-eras" tabindex="-1">Tabela Geral de Divisão de Eras <a class="header-anchor" href="#tabela-geral-de-divisao-de-eras" aria-label="Permalink to &quot;Tabela Geral de Divisão de Eras&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>70</td></tr><tr><td>Módulo</td><td>Eras Históricas e Eventos Importantes</td></tr><tr><td>Palavras-chave Principais</td><td>Divisão de eras, periodização histórica, ascensão de quatro estágios, linha do tempo, marco</td></tr></tbody></table><h2 id="i-principios-basicos-da-divisao-de-eras" tabindex="-1">I. Princípios Básicos da Divisão de Eras <a class="header-anchor" href="#i-principios-basicos-da-divisao-de-eras" aria-label="Permalink to &quot;I. Princípios Básicos da Divisão de Eras&quot;">​</a></h2><p>A divisão de eras históricas de Hengyuanzhou toma o caminho de ascensão de quatro estágios como estrutura fundamental e o estado de desenvolvimento do mecanismo de âncora como base central de periodização. Cada era corresponde a uma transformação fundamental na relação entre a civilização e o universo; os limites entre as eras não são pontos temporais arbitrários, mas são marcados por eventos importantes de significado cósmico.</p><p>A divisão de eras segue três princípios:</p><ul><li><strong>Princípio de correspondência de ascensão</strong>: cada grande era corresponde a um estágio no caminho de ascensão de quatro estágios, e os períodos subdivididos dentro de uma era correspondem aos avanços-chave dentro desse estágio</li><li><strong>Princípio de marcação por eventos</strong>: os pontos de início e fim de uma era são determinados por eventos importantes marcantes, não por uma simples divisão igual de tempo</li><li><strong>Princípio de estado civilizacional</strong>: cada era é nomeada pelas características centrais da civilização naquele período, refletindo as contradições principais e a direção de desenvolvimento da época</li></ul><h2 id="ii-tabela-geral-das-eras-historicas-de-hengyuanzhou" tabindex="-1">II. Tabela Geral das Eras Históricas de Hengyuanzhou <a class="header-anchor" href="#ii-tabela-geral-das-eras-historicas-de-hengyuanzhou" aria-label="Permalink to &quot;II. Tabela Geral das Eras Históricas de Hengyuanzhou&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número da Era</th><th>Nome da Era</th><th>Estágio de Ascensão Correspondente</th><th>Eventos Marcadores de Início-Fim</th><th>Características Centrais</th></tr></thead><tbody><tr><td>Primeira Era</td><td>Era Pré-Âncora</td><td>Antes da ascensão</td><td>Nascimento do universo→Despertar da primeira geração de âncoras</td><td>Cultivo predatório dominante, falhas civilizacionais frequentes</td></tr><tr><td>Segunda Era</td><td>Era do Despertar da Âncora</td><td>Início da fundação da realidade</td><td>Despertar da primeira geração de âncoras→Assinatura da Carta de Simbiose</td><td>Mecanismo de âncora estabelecido, germinação do pensamento anti-predatório</td></tr><tr><td>Terceira Era</td><td>Período de Estabelecimento do Sistema de Simbiose</td><td>Fundação da realidade</td><td>Assinatura da Carta de Simbiose→Abertura completa dos trezentos sistemas</td><td>Sistema de simbiose implementado, reconstrução social concluída</td></tr><tr><td>Quarta Era</td><td>Era de Abertura e Ativação do Sistema</td><td>Início do empoderamento tecnológico</td><td>Abertura dos trezentos sistemas→Conclusão da estratégia de ativação de 20%</td><td>Popularização do cultivo, avanços na engenharia de leis</td></tr><tr><td>Quinta Era</td><td>Era da Primeira Ascensão</td><td>Empoderamento tecnológico→Evolução da consciência</td><td>Sucesso da primeira ascensão→Estabelecimento da República de Todas as Raças</td><td>Verificação da ascensão civilizacional, avanço na interface do domínio da consciência</td></tr><tr><td>Sexta Era</td><td>Era da República de Todas as Raças</td><td>Evolução da consciência</td><td>Estabelecimento da República de Todas as Raças→Início da exploração entre planos</td><td>Unificação do sistema de todas as raças, simbiose da consciência coletiva</td></tr><tr><td>Sétima Era</td><td>Era da Exploração Entre Planos</td><td>Evolução da consciência→Simbiose interestelar</td><td>Início da exploração entre planos→Construção inicial da rede interestelar</td><td>Grandes descobertas de planos, expansão da rede de âncoras</td></tr><tr><td>Oitava Era</td><td>Era da Simbiose Interestelar</td><td>Simbiose interestelar</td><td>Construção da rede interestelar→Ascensão geral do universo</td><td>Simbiose universal de todas as raças, ascensão do universo em andamento</td></tr></tbody></table><h2 id="iii-duracao-temporal-e-indicadores-chave-de-cada-era" tabindex="-1">III. Duração Temporal e Indicadores-Chave de Cada Era <a class="header-anchor" href="#iii-duracao-temporal-e-indicadores-chave-de-cada-era" aria-label="Permalink to &quot;III. Duração Temporal e Indicadores-Chave de Cada Era&quot;">​</a></h2><p>Como Hengyuanzhou contém múltiplos planos e as velocidades do tempo diferem entre os planos, a duração temporal das eras é baseada no tempo padrão do plano principal:</p><table tabindex="0"><thead><tr><th>Era</th><th>Duração Estimada</th><th>Taxa de Cobertura de Âncora</th><th>Proporção de Cultivadores</th><th>Índice de Grau de Simbiose</th></tr></thead><tbody><tr><td>Era Pré-Âncora</td><td>Desconhecida (ordem de bilhões de anos)</td><td>0%</td><td>&lt;0,01%</td><td>&lt;10</td></tr><tr><td>Era do Despertar da Âncora</td><td>Milhares de anos</td><td>1%→10%</td><td>0,01%→1%</td><td>10→30</td></tr><tr><td>Período de Estabelecimento do Sistema de Simbiose</td><td>Séculos</td><td>10%→40%</td><td>1%→10%</td><td>30→50</td></tr><tr><td>Era de Abertura e Ativação do Sistema</td><td>Séculos</td><td>40%→70%</td><td>10%→30%</td><td>50→70</td></tr><tr><td>Era da Primeira Ascensão</td><td>Décadas</td><td>70%→85%</td><td>30%→50%</td><td>70→80</td></tr><tr><td>Era da República de Todas as Raças</td><td>Séculos</td><td>85%→95%</td><td>50%→70%</td><td>80→90</td></tr><tr><td>Era da Exploração Entre Planos</td><td>Milhares de anos</td><td>95%→99%</td><td>70%→90%</td><td>90→95</td></tr><tr><td>Era da Simbiose Interestelar</td><td>Em andamento</td><td>→100%</td><td>→100%</td><td>→100</td></tr></tbody></table><p>A taxa de cobertura de âncora refere-se à proporção de sub-regiões de plano onde o hardware de âncora foi implantado; a proporção de cultivadores refere-se à proporção de seres cobertos pelo sistema formal de cultivo; o índice de grau de simbiose é um indicador abrangente que mede o grau de simbiose da civilização, com pontuação máxima de 100.</p><h2 id="iv-logica-interna-da-evolucao-das-eras" tabindex="-1">IV. Lógica Interna da Evolução das Eras <a class="header-anchor" href="#iv-logica-interna-da-evolucao-das-eras" aria-label="Permalink to &quot;IV. Lógica Interna da Evolução das Eras&quot;">​</a></h2><p>A evolução das eras de Hengyuanzhou não é uma passagem linear do tempo, mas um processo evolutivo em espiral ascendente. Cada era resolve as contradições centrais deixadas pela era anterior e, ao mesmo tempo, gera as condições de desenvolvimento para a próxima era:</p><ul><li>A contradição fundamental da Era Pré-Âncora é a contradição entre predação e simbiose, cuja radicalização levou à inevitabilidade do despertar da âncora</li><li>A Era do Despertar da Âncora resolveu a questão de &quot;se a âncora existe&quot;, mas enfrentou o desafio institucional de &quot;a quem a âncora serve&quot;</li><li>O Período de Estabelecimento do Sistema de Simbiose concluiu a construção institucional, mas o monopólio dos recursos de cultivo ainda restringia a evolução das massas</li><li>A Era de Abertura e Ativação do Sistema quebrou o monopólio do cultivo, mas o salto na capacidade individual trouxe novos desafios éticos e de segurança</li><li>A Era da Primeira Ascensão verificou a viabilidade da ascensão, mas a ascensão de um único plano não foi suficiente para impulsionar a evolução geral do universo</li><li>A Era da República de Todas as Raças unificou o sistema civilizacional, mas ainda existem numerosos planos e raças não contatados no universo</li><li>A Era da Exploração Entre Planos expandiu as fronteiras da civilização, mas os planos dispersos precisam de uma conexão interestelar mais estreita</li><li>A Era da Simbiose Interestelar aponta finalmente para o objetivo último da ascensão geral do universo</li></ul><h2 id="v-posicionamento-da-era-atual" tabindex="-1">V. Posicionamento da Era Atual <a class="header-anchor" href="#v-posicionamento-da-era-atual" aria-label="Permalink to &quot;V. Posicionamento da Era Atual&quot;">​</a></h2><p>De acordo com o estado atual de desenvolvimento de Hengyuanzhou, a civilização está no ponto crítico de transição da Terceira Era (Período de Estabelecimento do Sistema de Simbiose) para a Quarta Era (Era de Abertura e Ativação do Sistema). O sistema de simbiose já foi implementado nos principais planos, o trabalho de abertura dos trezentos sistemas está avançando plenamente, e a estratégia de ativação de 20% entrou na fase de implementação. Várias tecnologias centrais na camada de engenharia de leis (motor de dedução de fruto de multiplicação, dispositivo de leis espaciais, sistema de espelho de cópia) passaram do laboratório para a produção em massa.</p><p>A tarefa central deste período de transição é: garantir que a abertura dos trezentos sistemas realmente beneficie todos os seres, e ao mesmo tempo cultivar o primeiro grupo de seres supremos de plano através da estratégia de ativação de 20%, acumulando energia e experiência suficientes para a primeira ascensão.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A Tabela Geral de Divisão de Eras é a estrutura macro para compreender a evolução histórica de Hengyuanzhou. Ela condensa a longa história do universo em oito eras com lógica interna clara, cada uma sendo um degrau necessário para a ascensão geral do universo. Os documentos subsequentes detalharão cada era e os eventos importantes dentro dela.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>71-Era Pré-Âncora</li><li>72-Era do Despertar da Âncora</li><li>76-Marco da Primeira Ascensão</li></ul>',22)])])}const h=e(r,[["render",i]]);export{p as __pageData,h as default};
